const aiResponse = $input.first().json;
const validatedData = $('Is Limit Reached?').first().json;
const filteredData = $('Filter for KI').first().json;

let subtasks = [];
let taskDescription = '';
let generatedTitle = '';

try {
  let content = aiResponse.content?.parts?.[0]?.text || '';

  if (!content) {
    throw new Error('AI response text content is empty.');
  }

  console.log('📝 RAW CONTENT:', content);

  content = content
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  console.log('🧹 CLEANED:', content);

  let parsed;

  try {
    parsed = JSON.parse(content);
  } catch (e) {
    const match = content.match(/(\{[\s\S]*\})/);
    if (match) {
      parsed = JSON.parse(match[1]);
    } else {
      throw new Error('Could not extract JSON from content');
    }
  }

  console.log('✅ PARSED:', JSON.stringify(parsed, null, 2));

  if (!parsed || typeof parsed !== 'object') {
    throw new Error('Parsed result is not an object');
  }

  if (parsed.title && typeof parsed.title === 'string') {
    generatedTitle = parsed.title.trim().substring(0, 80);
    console.log('🎯 AI Title:', generatedTitle);
  } else {
    console.warn('⚠️ No title in AI response, using original');
    generatedTitle = validatedData.title || filteredData.title;
  }

  if (parsed.description && typeof parsed.description === 'string') {
    taskDescription = parsed.description.trim();
    console.log('📄 AI Description:', taskDescription.substring(0, 100));
  } else {
    console.warn('⚠️ No description in AI response, using filtered');
    taskDescription = filteredData.description;
  }

  // ✅ Extrahiere Subtasks
  const rawSubtasks = parsed.subtasks || parsed.tasks || [];

  console.log('📋 Raw Subtasks:', JSON.stringify(rawSubtasks, null, 2));

  if (Array.isArray(rawSubtasks) && rawSubtasks.length > 0) {
    subtasks = rawSubtasks
      .map((st, idx) => {
        let title = '';

        if (typeof st === 'string') {
          title = st;
        } else if (st && typeof st === 'object') {
          title = st.title || st.name || st.description || '';
        }

        title = String(title).trim();

        if (!title) {
          console.warn(`⚠️ Subtask ${idx} has no title`);
          return null;
        }

        console.log(`✅ Subtask ${idx}: "${title}"`);

        return {
          id: `subtask_${Date.now()}_${idx}_${Math.random().toString(36).substr(2, 5)}`,
          title: title.substring(0, 255),
          completed: false
        };
      })
      .filter(st => st !== null);

    console.log(`✅ Created ${subtasks.length} subtasks`);
  } else {
    console.warn('⚠️ No subtasks found in AI response');
  }

} catch (error) {
  console.error('🔴 ERROR:', error.message);
  console.error('🔴 Raw AI Response:', aiResponse.content?.parts?.[0]?.text?.substring(0, 500));

  taskDescription = filteredData.description;
  subtasks = [];
  generatedTitle = validatedData.title || filteredData.title;
}

const finalTitle = generatedTitle || validatedData.title || 'Untitled Task';
const finalDescription = taskDescription || filteredData.description;

console.log('');
console.log('📦 FINAL OUTPUT:');
console.log('   Title:', finalTitle);
console.log('   Description:', finalDescription.substring(0, 100) + '...');
console.log('   Subtasks:', subtasks.length);

return {
  json: {
    ...validatedData,
    title: finalTitle,
    description: finalDescription,
    subtasks: subtasks,
    _aiGenerated: {
      title: !!generatedTitle,
      subtasks: subtasks.length > 0,
      hadErrors: !generatedTitle && subtasks.length === 0
    }
  }
};
